@file:OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)

package com.shimushili.ir

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import org.json.JSONArray

/** One row of data/ac_models.json (generated by tools/gen_ac_models.py). */
data class AcModel(val brand: String, val model: String, val kind: String, val protos: List<String>, val m: String?, val guess: Boolean)

object AcModels {
    private val normRe = Regex("[^\\p{L}\\p{N}]")
    fun norm(s: String) = s.uppercase().replace(normRe, "")

    val all: List<AcModel> by lazy {
        val txt = Device.app.assets.open("ac_models.json").bufferedReader().use { it.readText() }
        val a = JSONArray(txt)
        List(a.length()) { i ->
            val o = a.getJSONObject(i)
            val p = o.getJSONArray("protos")
            AcModel(
                o.getString("brand"), o.optString("model"), o.optString("kind", "ac"),
                List(p.length()) { p.getString(it) }, o.optString("m").ifEmpty { null }, o.optBoolean("guess"),
            )
        }
    }

    fun search(q: String): List<AcModel> {
        val n = norm(q)
        if (n.length < 2) return emptyList()
        return all.filter { norm(it.brand + it.model).contains(n) }
            .sortedBy { if (norm(it.model).startsWith(n)) 0 else if (it.guess) 1 else 2 }
            .take(40)
    }
}

fun acScenes() = listOf("מזגן כיבוי" to "כבה את המזגן בשלט", "קירור 24" to "קירור, 24°", "קירור 22" to "קירור, 22°", "חימום 26" to "חימום, 26°")
    .map { (n, h) -> LearnItem(n, "type=custom&g=ac&name=${enc(n)}", "כוון את השלט ל: $h, ולחץ על הכפתור האחרון.") }

/** Find the AC by what's printed on the remote or the indoor unit, then test it. */
@Composable
fun AcModelSearch(onDone: () -> Unit, onBack: () -> Unit) {
    var q by remember { mutableStateOf("") }
    var picked by remember { mutableStateOf<AcModel?>(null) }
    var idx by remember { mutableIntStateOf(0) }
    var learning by remember { mutableStateOf(false) }
    var protos by remember { mutableStateOf<Map<String, Int>>(emptyMap()) }
    LaunchedEffect(Unit) {
        protos = runCatching {
            val a = JSONArray(Api.callText("/api/acprotocols"))
            List(a.length()) { a.getJSONObject(it) }.associate { it.getString("name") to it.getInt("id") }
        }.getOrElse { emptyMap() }
    }
    if (learning) {
        StepScreen("❄️", "לימוד מצבי מזגן", "") {}
        LearnDialog("מצבי מזגן", acScenes()) { onDone() }
        return
    }
    val p = picked
    if (p == null) {
        StepScreen("🔎", "חיפוש לפי דגם", "הקלד את הדגם שכתוב על השלט (מאחור או בתא הסוללות) או על המזגן עצמו. אפשר גם שם מותג.") {
            OutlinedTextField(q, { q = it }, singleLine = true, label = { Text("למשל: YKR-M/003E או תדיראן") }, modifier = Modifier.fillMaxWidth())
            val res = remember(q) { AcModels.search(q) }
            if (q.length >= 2 && res.isEmpty()) Text("לא נמצא. נסה חלק מהדגם, או את שם המותג.")
            res.forEach { e ->
                Surface(
                    onClick = { picked = e; idx = 0 }, shape = RoundedCornerShape(14.dp),
                    color = MaterialTheme.colorScheme.surfaceVariant, modifier = Modifier.fillMaxWidth(),
                ) {
                    Column(Modifier.padding(14.dp)) {
                        Text(e.brand + if (e.model.isNotEmpty()) " · ${e.model}" else "", fontWeight = FontWeight.SemiBold)
                        Text(
                            if (e.guess) "ננסה כמה אפשרויות" else if (e.kind == "remote") "שלט" else "מזגן",
                            style = MaterialTheme.typography.bodySmall,
                        )
                    }
                }
            }
            TextButton(onClick = onBack) { Text("חזרה") }
        }
        return
    }
    val options = p.protos.filter { it in protos }
    if (protos.isNotEmpty() && idx >= options.size) {
        StepScreen("🤔", "לא הצלחנו להפעיל", "אין בעיה – אפשר ללמוד מצבים קבועים ישירות מהשלט שלך, וזה תמיד עובד.") {
            WideButton("למד מצבים מהשלט") { learning = true }
            TextButton(onClick = { picked = null }) { Text("חיפוש אחר") }
        }
        return
    }
    if (options.isNotEmpty()) {
        val proto = options[idx]
        LaunchedEffect(p, idx) {
            runCatching {
                Api.call("/api/settings?acproto=${protos[proto]}" + (p.m?.let { "&acmodelname=${enc(it)}" } ?: "&acmodel=-1"))
                Api.call("/api/ac?power=on&mode=cool&temp=24")
            }
        }
    }
    StepScreen(
        "❄️", p.brand + if (options.size > 1) " – בדיקה ${idx + 1} מתוך ${options.size}" else "",
        "שלחנו פקודת הפעלה (קירור 24°). המזגן נדלק?",
    ) {
        WideButton("כן, נדלק") { onDone() }
        WideButton("לא", primary = false) { idx++ }
        TextButton(onClick = { picked = null }) { Text("חזרה לחיפוש") }
    }
}
